import base64
import json
from pathlib import Path

OVERWRITE_EXISTING = False
TARGET = Path(r"D:\AI-Chatbot\data\legal_datasets\explainers_new.json")

_PAYLOAD_B64 = ""
EXPLAINERS = json.loads(base64.b64decode(_PAYLOAD_B64).decode("utf-8"))


def load_existing(path: Path) -> dict:
    if not path.exists():
        return {}
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError:
        return {}
    return data if isinstance(data, dict) else {}


def merge_explainers(existing: dict, incoming: dict) -> dict:
    merged = dict(existing)
    for key, value in incoming.items():
        if OVERWRITE_EXISTING or key not in merged:
            merged[key] = value
    return merged


TARGET.parent.mkdir(parents=True, exist_ok=True)
merged = merge_explainers(load_existing(TARGET), EXPLAINERS)
TARGET.write_text(json.dumps(merged, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
